  8	import java.net.http.HttpClient;
  9	import java.net.http.HttpRequest;
 10	import java.net.http.HttpResponse;
 11	import java.time.Clock;
 12	import java.time.Instant;
 13	import java.time.ZoneOffset;
 14	import java.util.Optional;
 15	import java.util.UUID;
 16	import java.util.function.Supplier;
 17	import shop.db.Database;
 18	import shop.db.Schema;
 19	import shop.domain.CarrierGateway;
 20	import shop.domain.Json;
 21	
 22	/** The real service on an in-memory H2 database (PostgreSQL mode) with a scripted carrier. */
 23	final class TestApp implements AutoCloseable {
 24	    record Reply(int status, String raw, JsonNode json) {
 25	    }
 26	
 27	    final HikariDataSource dataSource;
 28	    final Javalin server;
 29	    final HttpClient http = HttpClient.newHttpClient();
 30	    volatile Supplier<Optional<CarrierGateway.Quote>> carrier = () -> Optional.of(new CarrierGateway.Quote(
 31	            new java.math.BigDecimal("10.00"), 2));
 32	    volatile Instant now = Instant.parse("2026-10-14T15:30:00Z");
 33	
 34	    TestApp() {
 35	        this(null);
 36	    }
 37	
 38	    TestApp(HikariDataSource shared) {
 39	        try {
 40	            if (shared == null) {
 41	                HikariConfig cfg = new HikariConfig();
 42	                cfg.setJdbcUrl("jdbc:h2:mem:" + UUID.randomUUID() + ";MODE=PostgreSQL;DB_CLOSE_DELAY=-1");
 43	                cfg.setMaximumPoolSize(8);
 44	                shared = new HikariDataSource(cfg);
 45	                Schema.init(shared);
 46	            }
 47	            dataSource = shared;
 48	        } catch (Exception e) {
 49	            throw new IllegalStateException(e);
 50	        }
 51	        CarrierGateway gateway = (zip, grams, service) -> carrier.get();
 52	        Clock clock = new Clock() {
 53	            public java.time.ZoneId getZone() { return ZoneOffset.UTC; }
 54	            public Clock withZone(java.time.ZoneId z) { return this; }
 55	            public Instant instant() { return now; }
 56	        };
 57	        server = Main.wire(new Database(dataSource), gateway, clock).create().start(0);
 58	    }
 59	
 60	    Reply call(String method, String path, String body) {
 61	        try {
 62	            HttpRequest.Builder b = HttpRequest.newBuilder(URI.create("http://localhost:" + server.port() + path));
 63	            b.header("Content-Type", "application/json");
 64	            b.method(method, body == null ? HttpRequest.BodyPublishers.noBody()
 65	                    : HttpRequest.BodyPublishers.ofString(body));
 66	            HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 67	            return new Reply(r.statusCode(), r.body(), Json.MAPPER.readTree(r.body()));
 68	        } catch (Exception e) {
 69	            throw new IllegalStateException(e);
 70	        }
 71	    }
 72	
 73	    Reply get(String path) {
 74	        return call("GET", path, null);
 75	    }
 76	
 77	    Reply post(String path, String body) {
 78	        return call("POST", path, body);
 79	    }
 80	
 81	    void carrierReplies(int cents, int hours) {
 82	        carrier = () -> Optional.of(new CarrierGateway.Quote(java.math.BigDecimal.valueOf(cents, 2), (hours + 23) / 24));
 83	    }
 84	
 85	    @Override
 86	    public void close() {
 87	        server.stop();
 88	        dataSource.close();
 89	    }
 90	}
