 93	import static org.junit.jupiter.api.Assertions.*;
 94	
 95	import com.sun.net.httpserver.HttpServer;
 96	import java.net.InetSocketAddress;
 97	import java.nio.charset.StandardCharsets;
 98	import java.util.concurrent.atomic.AtomicReference;
 99	import org.junit.jupiter.api.Test;
100	import shop.app.TransLogClient;
101	import shop.domain.CarrierGateway;
102	
103	class TransLogClientTest {
104	    @Test
105	    void translatesTransLogAnswers() throws Exception {
106	        AtomicReference<String> body = new AtomicReference<>();
107	        AtomicReference<Integer> status = new AtomicReference<>(200);
108	        AtomicReference<String> query = new AtomicReference<>();
109	        HttpServer server = HttpServer.create(new InetSocketAddress(0), 0);
110	        server.createContext("/v2/quote", ex -> {
111	            query.set(ex.getRequestURI().getRawQuery());
112	            if ("SLOW".equals(body.get())) {
113	                try {
114	                    Thread.sleep(3000);
115	                } catch (InterruptedException ignored) {
116	                }
117	            }
118	            byte[] bytes = String.valueOf(body.get()).getBytes(StandardCharsets.UTF_8);
119	            ex.sendResponseHeaders(status.get(), bytes.length);
120	            ex.getResponseBody().write(bytes);
121	            ex.close();
122	        });
123	        server.start();
124	        try {
125	            TransLogClient client = new TransLogClient("http://localhost:" + server.getAddress().getPort() + "/");
126	            body.set("{\"price_cents\":3310,\"eta_hours\":41}");
127	            var quote = client.quote("01310100", 1800, "EXP").orElseThrow();
128	            assertEquals("33.10", quote.cost().toPlainString());
129	            assertEquals(2, quote.days());
130	            assertEquals("zip=01310100&weight_g=1800&service=EXP", query.get());
131	
132	            body.set("{\"error\":\"ZIP_NOT_SERVED\"}");
133	            assertTrue(client.quote("01310100", 1800, "STD").isEmpty());
134	
135	            body.set("{\"error\":\"OTHER\"}");
136	            assertThrows(CarrierGateway.UnavailableException.class, () -> client.quote("01310100", 1, "STD"));
137	            body.set("{\"price_cents\":3310}");
138	            assertThrows(CarrierGateway.UnavailableException.class, () -> client.quote("01310100", 1, "STD"));
139	            body.set("{}");
140	            status.set(500);
141	            assertThrows(CarrierGateway.UnavailableException.class, () -> client.quote("01310100", 1, "STD"));
142	            status.set(200);
143	            body.set("SLOW");
144	            assertThrows(CarrierGateway.UnavailableException.class, () -> client.quote("01310100", 1, "STD"));
145	        } finally {
146	            server.stop(0);
147	        }
148	    }
149	}

