  1	package shop;
  2	
  3	import static org.junit.jupiter.api.Assertions.*;
  4	
  5	import java.time.Instant;
  6	import java.util.ArrayList;
  7	import java.util.List;
  8	import java.util.Optional;
  9	import java.util.concurrent.Callable;
 10	import java.util.concurrent.ExecutorService;
 11	import java.util.concurrent.Executors;
 12	import java.util.concurrent.Future;
 13	import org.junit.jupiter.api.AfterEach;
 14	import org.junit.jupiter.api.BeforeEach;
 15	import org.junit.jupiter.api.Test;
 16	import shop.TestApp.Reply;
 17	
 18	class ShopTest {
 19	    TestApp app;
 20	
 21	    @BeforeEach
 22	    void start() {
 23	        app = new TestApp();
 24	    }
 25	
 26	    @AfterEach
 27	    void stop() {
 28	        app.close();
 29	    }
 30	
 31	    static String purchase(String items, String ship, String coupon, String pay, int installments, String tier,
 32	                           String region) {
 33	        return purchase("12345678909", items, ship, coupon, pay, installments, tier, region);
 34	    }
 35	
 36	    static String purchase(String cpf, String items, String ship, String coupon, String pay, int installments,
 37	                           String tier, String region) {
 38	        return "{\"customer\":{\"cpf\":\"" + cpf + "\",\"email\":\"a@b.com\"},\"items\":" + items
 39	                + ",\"zipCode\":\"01310100\",\"region\":\"" + region + "\",\"shippingMethod\":\"" + ship + "\""
 40	                + (coupon == null ? "" : ",\"coupon\":\"" + coupon + "\"")
 41	                + ",\"paymentMethod\":\"" + pay + "\",\"installments\":" + installments
 42	                + ",\"clubTier\":\"" + tier + "\"}";
 43	    }
 44	
 45	    static String items(Object... skuQty) {
 46	        StringBuilder sb = new StringBuilder("[");
 47	        for (int i = 0; i < skuQty.length; i += 2) {
 48	            sb.append(i > 0 ? "," : "").append("{\"sku\":\"").append(skuQty[i]).append("\",\"quantity\":")
 49	                    .append(skuQty[i + 1]).append("}");
 50	        }
 51	        return sb.append("]").toString();
 52	    }
 53	
 54	    void assertSummary(Reply r, String sub, String cupom, String frete, int prazo, String seguro, String ajuste,
 55	                       String total, int n, String parcela, String credito, boolean brinde) {
 56	        assertEquals(200, r.status(), r.raw());
 57	        assertEquals("{\"productsSubtotal\":" + sub + ",\"couponDiscount\":" + cupom + ",\"shippingCost\":" + frete
 58	                + ",\"deliveryDays\":" + prazo + ",\"insurance\":" + seguro + ",\"paymentAdjustment\":" + ajuste
 59	                + ",\"finalTotal\":" + total + ",\"installments\":" + n + ",\"installmentAmount\":" + parcela
 60	                + ",\"nextPurchaseCredit\":" + credito + ",\"gift\":" + brinde + "}", r.raw());
 61	    }
 62	
 63	    Reply summary(String body) {
 64	        return app.post("/checkout/summary", body);
 65	    }
 66	
 67	    @Test
 68	    void examples() {
 69	        String cam2ten = items("CAM-001", 2, "TEN-001", 1);
 70	        app.carrierReplies(3310, 41);
 71	        assertSummary(summary(purchase(cam2ten, "EXPRESS", "WELCOME10", "PIX", 1, "BRONZE", "NORTH")),
 72	                "409.70", "40.97", "33.10", 5, "10.24", "0.00", "412.07", 1, "412.07", "0.00", false);
 73	        app.carrierReplies(1560, 168);
 74	        assertSummary(summary(purchase(cam2ten, "ECONOMY", null, "CREDIT_CARD", 6, "SILVER", "MIDWEST")),
 75	                "409.70", "0.00", "15.60", 7, "6.15", "30.55", "462.00", 6, "77.00", "8.19", false);
 76	        assertSummary(summary(purchase(items("FON-001", 2), "COURIER", "MINUS50", "BANK_SLIP", 1, "GOLD", "NORTHEAST")),
 77	                "399.80", "50.00", "18.00", 0, "8.00", "3.49", "379.29", 1, "379.29", "19.99", false);
 78	        assertSummary(summary(purchase(items("MEI-001", 7, "CAM-001", 2), "STORE_PICKUP", "BUY3PAY2", "CREDIT_CARD", 3,
 79	                "SILVER", "SOUTH")),
 80	                "299.10", "39.80", "0.00", 1, "2.99", "0.00", "262.29", 3, "87.43", "5.98", false);
 81	        app.carrierReplies(2475, 30);
 82	        assertSummary(summary(purchase(items("CAM-001", 3), "EXPRESS", "BUY3PAY2", "PIX", 1, "BRONZE", "SOUTHEAST")),
 83	                "239.70", "71.91", "24.75", 2, "2.40", "0.00", "194.94", 1, "194.94", "0.00", false);
 84	        app.carrierReplies(2210, 150);
 85	        assertSummary(summary(purchase(items("MEI-001", 1), "ECONOMY", "FREESHIPPING", "BANK_SLIP", 1, "BRONZE", "SOUTH")),
 86	                "19.90", "5.97", "22.10", 7, "0.20", "3.49", "39.72", 1, "39.72", "0.00", false);
 87	        app.carrierReplies(5080, 49);
 88	        assertSummary(summary(purchase(items("JAQ-001", 3, "TEN-001", 1), "EXPRESS", null, "PIX", 1, "GOLD", "NORTH")),
 89	                "1419.60", "0.00", "0.00", 6, "30.00", "-72.48", "1377.12", 1, "1377.12", "70.98", true);
 90	    }
 91	
 92	    void assertError(Reply r, int status, String code) {
 93	        assertEquals(status, r.status(), r.raw());
 94	        assertEquals("{\"error\":\"" + code + "\"}", r.raw());
 95	    }
 96	
 97	    @Test
 98	    void refusals() {
 99	        assertError(summary(purchase(items("CAM-001", 1), "STORE_PICKUP", "FREESHIPPING", "PIX", 1, "SILVER", "SOUTHEAST")),
100	                422, "COUPON_NOT_APPLICABLE");
101	        app.carrier = Optional::empty;
102	        assertError(summary(purchase(items("TEN-001", 1), "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH")),
103	                422, "SHIPPING_METHOD_UNAVAILABLE");
104	        app.carrier = () -> {
105	            throw new shop.domain.CarrierGateway.UnavailableException("down", null);
106	        };
107	        assertError(summary(purchase(items("TEN-001", 1), "EXPRESS", null, "PIX", 1, "BRONZE", "NORTH")),
108	                503, "CARRIER_UNAVAILABLE");
109	        assertError(summary(purchase(items("JAQ-001", 1), "COURIER", "", "PIX", 1, "BRONZE", "NORTH")),
110	                422, "INVALID_COUPON");
111	        assertError(summary(purchase(items("JAQ-001", 3), "COURIER", null, "BANK_SLIP", 1, "BRONZE", "SOUTH")),
112	                422, "PAYMENT_METHOD_UNAVAILABLE");
113	        assertError(summary(purchase(items("TEN-001", 5, "MOC-001", 2), "COURIER", null, "PIX", 1, "BRONZE", "SOUTH")),
114	                422, "INSUFFICIENT_STOCK");
115	        assertError(summary(purchase(items("TEN-001", 5), "COURIER", null, "PIX", 1, "BRONZE", "SOUTH")),
116	                422, "SHIPPING_METHOD_UNAVAILABLE");
117	        assertError(summary(purchase(items("REL-001", 1, "XXX", 1), "COURIER", null, "PIX", 1, "BRONZE", "SOUTH")),
118	                422, "UNKNOWN_PRODUCT");
119	        assertError(summary(purchase(items("REL-001", 1), "COURIER", null, "PIX", 1, "BRONZE", "SOUTH")),
120	                422, "PRODUCT_DISCONTINUED");
121	        assertError(summary(purchase(items("CAM-001", 1, "CAM-001", 1), "COURIER", null, "PIX", 1, "BRONZE", "SOUTH")),
122	                422, "INVALID_ORDER");
123	        assertError(summary(purchase(items("CAM-001", 1), "COURIER", null, "PIX", 2, "BRONZE", "SOUTH")),
124	                422, "INVALID_INSTALLMENTS");
125	        assertError(summary("garbage"), 422, "INVALID_ORDER");
126	        assertError(app.get("/orders/nope"), 404, "ORDER_NOT_FOUND");
127	        assertError(app.get("/products/nope"), 404, "PRODUCT_NOT_FOUND");
128	        assertError(app.get("/customers/1/notifications"), 404, "CUSTOMER_NOT_FOUND");
129	        assertError(app.post("/notifications/x/read", null), 404, "NOTIFICATION_NOT_FOUND");
130	    }
131	
132	    String register(String cpf, String items, String tier) {
133	        app.carrierReplies(1000, 24);
134	        Reply r = app.post("/orders", purchase(cpf, items, "ECONOMY", null, "PIX", 1, tier, "SOUTH"));
135	        assertEquals(201, r.status(), r.raw());
136	        assertEquals("AWAITING_PAYMENT", r.json().get("status").asText());
137	        return r.json().get("id").asText();
138	    }
139	
140	    Reply pay(String id, String tx, String paidAt) {
141	        return app.post("/orders/" + id + "/payment", "{\"transactionId\":\"" + tx + "\",\"paidAt\":\"" + paidAt + "\"}");
142	    }
143	
144	    int stock(String sku) {
145	        return app.get("/products/" + sku).json().get("stock").asInt();
146	    }
147	
148	    String credit(String cpf) {
149	        return app.get("/customers/" + cpf).raw().replaceAll(".*\"creditBalance\":([0-9.]+).*", "$1");
150	    }
151	
152	    @Test
153	    void paymentLifecycleAndIdempotency() {
154	        String id = register("111", items("CAM-001", 2), "SILVER");
155	        assertEquals(50, stock("CAM-001"));
156	        Reply first = pay(id, "TX1", "2026-10-14T16:00:00Z");
157	        assertEquals(200, first.status(), first.raw());
158	        assertEquals("PAID", first.json().get("status").asText());
159	        Reply again = pay(id, "TX1", "2026-10-14T16:00:00Z");
160	        assertEquals(first.raw(), again.raw());
161	        assertEquals(48, stock("CAM-001"));
162	        assertEquals("3.20", credit("111"));
163	        assertError(pay(id, "TX2", "2026-10-14T16:00:00Z"), 409, "OPERATION_NOT_ALLOWED");
164	        assertEquals(1, app.get("/customers/111/notifications").json().size());
165	
166	        assertError(app.post("/orders/" + id + "/shipment", "{}"), 422, "INVALID_ORDER");
167	        Reply shipped = app.post("/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}");
168	        assertEquals("SHIPPED", shipped.json().get("status").asText());
169	        assertEquals("BR1", shipped.json().get("trackingCode").asText());
170	        assertError(app.post("/orders/" + id + "/cancellation", null), 409, "OPERATION_NOT_ALLOWED");
171	        assertEquals("DELIVERED", app.post("/orders/" + id + "/delivery", null).json().get("status").asText());
172	    }
173	
174	    @Test
175	    void cancelPaidOrderGivesEverythingBack() {
176	        String id = register("222", items("CAM-001", 2), "GOLD");
177	        pay(id, "T", "2026-10-14T16:00:00Z");
178	        assertEquals(48, stock("CAM-001"));
179	        assertEquals("7.99", credit("222"));
180	        assertEquals("CANCELLED", app.post("/orders/" + id + "/cancellation", null).json().get("status").asText());
181	        assertEquals(50, stock("CAM-001"));
